interface LlmClient {
    public function complete(string $prompt): string;
}

final class AnthropicClient implements LlmClient { /* ... */
    public function complete(string $prompt): string { /* call API */ return ''; }
}
final class OpenAiClient implements LlmClient { /* ... */
    public function complete(string $prompt): string { /* call API */ return ''; }
}

// Strategy + DI: the caller doesn't care which provider it is.
final class Summariser {
    public function __construct(private LlmClient $llm) {}
    public function summarise(string $text): string {
        return $this->llm->complete("Summarise:\n\n{$text}");
    }
}

// A queued job that calls an LLM off the request cycle.
class GenerateSummary implements ShouldQueue {
    public function __construct(public int $articleId) {}

    public function handle(Summariser $summariser): void {
        $article = Article::findOrFail($this->articleId);
        $article->update([
            'summary' => $summariser->summarise($article->body),
        ]);
    }
}

// Dispatch it from a controller — returns instantly, work runs in background.
GenerateSummary::dispatch($article->id);

