$messages = [['role' => 'user', 'content' => $task]];

for ($step = 0; $step < MAX_STEPS; $step++) {
    $reply = $llm->respond($messages, tools: $tools);

    if ($reply->isFinalAnswer()) {
        return $reply->text;                 // stop condition
    }

    $result = $toolRegistry->run(            // execute the requested tool
