        $reply->toolArgs,
    );

    $messages[] = $reply->asAssistantTurn();
    $messages[] = ['role' => 'tool', 'content' => $result];
}

public function handle(Request $request): Response {
    // 1. Verify signature (reject forgeries)
    if (! $this->signatureValid($request)) {
        return response('invalid signature', 401);
    }

    $eventId = $request->input('id');

    // 2. Idempotency: skip events we've already processed
    if (ProcessedEvent::where('event_id', $eventId)->exists()) {
        return response('ok', 200);
    }
    ProcessedEvent::create(['event_id' => $eventId]);

    // 3. Offload work, ack immediately
    ProcessWebhook::dispatch($request->all());
    return response('ok', 200);
}

// Typed, resilient fetch to your PHP backend
interface Article { id: number; title: string; status: 'draft' | 'published'; }

async function getArticles(): Promise<Article[]> {
  const res = await fetch('/v1/articles', {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const { data } = (await res.json()) as { data: Article[] };
  return data;
}
